<template><section aria-label="受审排班计划入口"><p v-if="!allowed">当前身份无法访问此排班计划范围。</p><template v-else><p>完整本科人员、受审原来源、明确日期会话与每人每会话的原声明，按当前捕获核对。场景净容量与候选等待人工复核。</p><el-form inline @submit.prevent="page=1;load()"><el-form-item label="受审排班原科室"><el-select :model-value="department" aria-label="受审排班原科室" clearable filterable @update:model-value="department=$event||null"><el-option v-for="row in departments" :key="row.department_id" :value="row.department_id" :label="`${row.name||'原科室'} · #${row.department_id}`" /></el-select></el-form-item><el-button native-type="submit" :loading="loading">读取受审排班计划</el-button><el-button v-if="department" @click="sourceOpen=true">登记或核对排班原来源</el-button><el-button v-if="canRecord" @click="openCreator">新建完整排班场景草稿</el-button><el-button v-if="chosen" @click="clearChoice">清除所选排班计划</el-button></el-form><p v-if="error" role="alert">{{ error }}</p><p v-if="notice">{{ notice }}</p>
 <el-table :data="items" v-loading="loading" aria-label="受审排班计划目录"><el-table-column label="原计划与科室" min-width="300"><template #default="{row}">{{ row.plan_id }} · 科室 #{{ row.department_id }}<br />当前捕获 {{ row.created_at }}</template></el-table-column><el-table-column label="治理与原集合" min-width="200"><template #default="{row}">{{ rosterSourceStates[row.status] }} v{{ row.revision }}；{{ row.eligible?'当前可用于新计算':'当前不可用于新计算' }}</template></el-table-column><el-table-column label="明确操作" width="260"><template #default="{row}"><el-button @click="inspect(row)">核对受审排班原计划</el-button><el-button v-if="!governance&&row.eligible" :disabled="checking" @click="inspect(row,true)">选择受审排班计划</el-button></template></el-table-column></el-table><p>共 {{ total }} 件，选择计划查看完整资料。</p><el-pagination v-if="total>20" v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load" />
 </template>
 <el-dialog v-model="sourceOpen" title="排班原来源与新计划边界" width="min(1200px,98vw)"><roster-sources v-if="sourceOpen&&department&&allowed" :department-id="department" :governance="governance" :active="sourceOpen&&active" @source-changed="sourceChanged" /></el-dialog>
 <el-dialog v-model="creatorOpen" title="完整排班场景原声明与集合预览" width="min(1150px,98vw)"><template v-if="creatorOpen&&canRecord"><plan-form :key="formKey" ref="form" :department-id="department" :doctors="options.doctors" :disabled="saving||previewing" @change="invalidate" @validity="formValid=$event" /><p v-if="createError" role="alert">{{ createError }}</p><el-button :loading="previewing" :disabled="!formValid||saving" @click="preview">预览全部人员与原来源集合</el-button><template v-if="captured"><p>已核对完整人员 {{ captured.cohort.length }} 人、全部原来源 {{ captured.fact_manifest.length }} 件；当前捕获，不冒称旧截止已知。</p><p class="hash">完整集合 {{ captured.collection_digest }}<br />规划原UTC {{ captured.planning_start_at }} 至 {{ captured.planning_end_at }}</p><el-button :loading="saving" :disabled="saving||!formValid" @click="save">仅保存完整排班场景草稿</el-button></template></template></el-dialog>
 <el-dialog v-model="detailOpen" title="受审排班完整原件核对" width="min(1100px,98vw)" @closed="!detailOpen&&clearDetail()"><p v-if="detailError" role="alert">{{ detailError }}</p><template v-if="allowed&&detail"><p class="hash">原计划 {{ detail.source_id }}；科室 #{{ detail.department_id }}<br />完整私有原件 {{ detail.content_hash }}<br />公开投影 {{ detail.projection_hash??'尚未发布，无公开投影' }}<br />当前治理 {{ detail.governance_hash }} · {{ rosterSourceStates[detail.status] }} v{{ detail.revision }}</p><p>{{ detail.eligible?'当前受审原集合与规划范围可纳入新计算':'当前不可用于新计算' }}；{{ detail.exclusion_reasons.join('；') }}</p><template v-if="detail.snapshot"><p>完整人员 {{ detail.snapshot.cohort.length }}、原来源 {{ detail.snapshot.facts.length }}、会话 {{ detail.snapshot.request.sessions.length }}、配对 {{ detail.snapshot.request.options.length }}。业务时区 {{ detail.snapshot.request.business_timezone }}；{{ detail.snapshot.request.date_from }} 至 {{ detail.snapshot.request.date_to }}。</p><p v-if="detail.audit_only&&!detail.eligible">超级管理员冻结审计保留原件，不能恢复失效计划供新任务使用。</p><details><summary>院内核对完整排班原声明与冻结来源</summary><p>原人员身份、原来源正文和自由依据仅院内核对；专用优化服务只接收脱敏公开投影。</p><pre>{{ JSON.stringify(detail.snapshot,null,2) }}</pre></details></template><p v-else>原场景和审核备注当前已隐藏，只保留原治理元数据。</p><p v-if="detail.review_basis_note">原审核依据：{{ detail.review_basis_note }}</p><p v-if="detail.revoke_reason">原撤销依据：{{ detail.revoke_reason }}</p>
 <template v-if="detail.can_review&&roles.includes('super_admin')"><el-input v-model="reviewBasis" aria-label="排班计划审核依据" type="textarea" maxlength="4000" placeholder="至少20个非空白字符，不超过4000 UTF8字节；明确核对完整集合、适用范围和场景容量" /><el-button :disabled="acting||!rosterReviewBasisValid(reviewBasis)" :loading="acting" @click="act('publish')">审核并发布此排班计划</el-button><el-button :disabled="acting||!rosterReviewBasisValid(reviewBasis)" :loading="acting" @click="act('reject')">审核并拒绝此排班计划</el-button></template><template v-if="detail.can_revoke"><el-input v-model="reason" aria-label="排班计划撤销依据" type="textarea" maxlength="1000" /><el-button type="danger" :disabled="acting||!reason.trim()" :loading="acting" @click="act('revoke')">撤销此受审排班计划</el-button></template></template></el-dialog>
</section></template>
<script setup>
import {computed,defineAsyncComponent,onActivated,onBeforeUnmount,onDeactivated,ref,watch} from 'vue';import {useStore} from 'vuex';import {getRosterSourceOptions,rosterPositive,rosterReviewBasisValid,rosterSourceStates} from '@/api/rosterSources';import {createRosterPlan,getAdminRosterPlan,getAdminRosterPlans,getRosterPlan,getRosterPlans,previewRosterPlan,reviewRosterPlan,revokeRosterPlan,rosterPlanMetadataValid,rosterPlanRequestValid,rosterReferencesValid,verifyRosterPlan,verifyRosterPlanTransition,verifyRosterPreview} from '@/api/rosterPlans';import {supportCanonical} from '@/api/inpatientSupport';
const PlanForm=defineAsyncComponent(()=>import('./PlanForm.vue')),RosterSources=defineAsyncComponent(()=>import('@/components/AIRosterSources/index.vue'));
const props=defineProps({departmentId:{type:Number,default:null},initialReferences:{type:Object,default:null},governance:{type:Boolean,default:false},active:{type:Boolean,default:true}}),emit=defineEmits(['selection','availability','department-change','invalidate']),store=useStore(),roles=computed(()=>store.getters['user/permissions']||[]),allowed=computed(()=>props.active&&!!store.state.user.accessToken&&(props.governance?roles.value.includes('super_admin'):roles.value.some(role=>['admin','director','super_admin'].includes(role))));
const department=ref(props.departmentId),departments=ref([]),options=ref(null),items=ref([]),total=ref(0),page=ref(1),loading=ref(false),error=ref(''),notice=ref(''),sourceOpen=ref(false),creatorOpen=ref(false),form=ref(null),formKey=ref(0),formValid=ref(false),captured=ref(null),capturedRequest=ref(null),previewing=ref(false),saving=ref(false),createError=ref(''),detailOpen=ref(false),detail=ref(null),detailError=ref(''),reviewBasis=ref(''),reason=ref(''),acting=ref(false),checking=ref(false),chosen=ref(null);
let epoch=0,seq=0,previewSeq=0,detailSeq=0,alive=true,paused=false;const identity=()=>supportCanonical([department.value,props.active,props.governance,props.initialReferences,store.state.user.accessToken,store.state.user.username,roles.value]),ticket=()=>({epoch,key:identity()}),current=t=>alive&&!paused&&allowed.value&&t.epoch===epoch&&t.key===identity(),canRecord=computed(()=>allowed.value&&rosterPositive(department.value)&&options.value?.department_id===department.value&&options.value.can_record===true);
function clearChoice(){chosen.value=null;emit('selection',null);emit('availability',false);}
function invalidate(){previewSeq++;captured.value=capturedRequest.value=null;previewing.value=false;clearChoice();emit('invalidate');}
function clearDetail(){detailSeq++;detail.value=null;detailError.value=reviewBasis.value=reason.value='';acting.value=checking.value=false;}
function reset(){epoch++;seq++;options.value=null;departments.value=[];items.value=[];total.value=0;page.value=1;loading.value=false;sourceOpen.value=creatorOpen.value=detailOpen.value=false;clearDetail();invalidate();formKey.value++;formValid.value=false;saving.value=false;error.value=createError.value=notice.value='';}
function optionsValid(data){return data?.provider_required===false&&Array.isArray(data.source_kinds)&&supportCanonical(data.source_kinds)===supportCanonical(['qualification','duty_interval','availability','work_rule_policy']);}
async function refresh(){const t=ticket();if(!current(t))return;try{const response=await getRosterSourceOptions(),data=response.data;if(!current(t))return;if(!optionsValid(data)||!Array.isArray(data.departments)||data.departments.length>2000||new Set(data.departments.map(row=>row.department_id)).size!==data.departments.length||data.departments.some(row=>!rosterPositive(row.department_id)||row.name!==null&&typeof row.name!=='string'))throw new Error('实际授权科室目录无法核对');departments.value=data.departments;if(department.value){const response=await getRosterSourceOptions({department_id:department.value}),data=response.data;if(!current(t))return;if(!optionsValid(data)||data.department_id!==department.value||data.schema_version!=='roster_fact_v1'||typeof data.can_record!=='boolean'||data.personnel_collection_complete_in_database!==true||data.personnel_qualification_verified!==false||!Array.isArray(data.doctors)||data.doctors.length>512||new Set(data.doctors.map(row=>row.doctor_id)).size!==data.doctors.length||data.doctors.some(row=>!rosterPositive(row.doctor_id)||row.department_id!==department.value))throw new Error('完整本科人员超过容量或原范围无法核对，未截断');options.value=data;}await load();if(!props.governance&&rosterReferencesValid(props.initialReferences)&&current(t)){const response=await getRosterPlan(props.initialReferences.roster_plan_id),row=response.data;if(!current(t))return;if(row.plan_id!==props.initialReferences.roster_plan_id||!await verifyRosterPlan(row)||!row.eligible)throw new Error('绑定排班原计划当前不可用或原件不一致');if(!current(t))return;if(department.value===null){department.value=row.department_id;return;}if(row.department_id!==department.value)throw new Error('绑定排班原计划与明确科室不一致');await inspect(row,true);}}catch(failure){if(current(t))error.value=failure?.message||'受审排班范围读取失败';}}
async function load(){const t=ticket(),n=++seq,query={...(department.value?{department_id:department.value}:{}),page:page.value,page_size:20};items.value=[];total.value=0;if(!current(t)||!props.governance&&!department.value)return;loading.value=true;try{const response=await(props.governance?getAdminRosterPlans:getRosterPlans)(query),data=response.data;if(!current(t)||n!==seq)return;if(!Array.isArray(data?.items)||data.page!==page.value||data.page_size!==20||!Number.isSafeInteger(data.total)||data.total<0||data.items.length>20||data.items.length>data.total||new Set(data.items.map(row=>row.plan_id)).size!==data.items.length||data.items.some(row=>!rosterPlanMetadataValid(row,department.value)))throw new Error('受审计划目录与原科室或完整元数据不一致');items.value=data.items;total.value=data.total;}catch(failure){if(current(t)&&n===seq)error.value=failure?.message||'受审计划目录读取失败';}finally{if(current(t)&&n===seq)loading.value=false;}}
async function inspect(original,choose=false){clearDetail();const t=ticket(),n=detailSeq;checking.value=true;if(!choose)detailOpen.value=true;try{const response=await(props.governance?getAdminRosterPlan:getRosterPlan)(original.plan_id),row=response.data;if(!current(t)||n!==detailSeq)return;if(row.audit_only!==roles.value.includes('super_admin')||!await verifyRosterPlan(row,original.department_id,{audit:props.governance})||row.plan_id!==original.plan_id||row.content_hash!==original.content_hash||row.governance_hash!==original.governance_hash||row.projection_hash!==original.projection_hash)throw new Error('受审原计划、完整投影、治理版本或原范围已变化，请刷新重核');if(!current(t)||n!==detailSeq)return;if(choose){if(!row.eligible||!row.public_source||props.initialReferences?.roster_plan_id&&props.initialReferences.roster_plan_id!==row.plan_id)throw new Error('请明确选择当前原计划且核对原入口绑定');chosen.value=row;emit('selection',{roster_plan_id:row.plan_id});emit('availability',true);}else detail.value=row;}catch(failure){if(current(t)&&n===detailSeq){detailError.value=failure?.message||'完整排班原件无法核对';if(choose){clearChoice();error.value=detailError.value;}}}finally{if(current(t)&&n===detailSeq)checking.value=false;}}
async function preview(){if(!formValid.value||previewing.value)return;const t=ticket(),n=++previewSeq;let request;try{request=form.value.build();if(!rosterPlanRequestValid(request))return;}catch{return;}previewing.value=true;createError.value='';captured.value=capturedRequest.value=null;try{const response=await previewRosterPlan(request),value=response.data;if(!current(t)||n!==previewSeq)return;if(!await verifyRosterPreview(value,request))throw new Error('完整人员、原来源清单或场景时刻无法逐项核对');if(current(t)&&n===previewSeq){captured.value=value;capturedRequest.value=request;}}catch(failure){if(current(t)&&n===previewSeq)createError.value=failure?.message||'完整来源预览失败';}finally{if(current(t)&&n===previewSeq)previewing.value=false;}}
async function save(){if(!canRecord.value||!formValid.value||!captured.value||saving.value)return;const t=ticket(),n=previewSeq,request=capturedRequest.value,collection=captured.value.collection_digest;if(supportCanonical(form.value.build())!==supportCanonical(request)){invalidate();return;}saving.value=true;try{const response=await createRosterPlan({request,expected_collection_digest:collection}),row=response.data;if(!current(t)||n!==previewSeq)return;if(!await verifyRosterPlan(row,department.value)||row.audit_only!==roles.value.includes('super_admin')||row.status!=='draft'||row.collection_digest!==collection||supportCanonical(row.snapshot.request)!==supportCanonical(request))throw new Error('新排班草稿回执与完整原请求、原人员集合或摘要不一致');if(!current(t)||n!==previewSeq)return;creatorOpen.value=false;formKey.value++;invalidate();notice.value='完整排班场景草稿已保存，尚未审核发布或修改实际业务。';await load();}catch(failure){if(current(t)&&n===previewSeq)createError.value=failure?.message||'排班场景草稿登记失败';}finally{if(current(t))saving.value=false;}}
async function act(action){const original=detail.value;if(!original||acting.value||!current(ticket())||!['publish','reject','revoke'].includes(action)||(action==='revoke'?!original.can_revoke||!reason.value.trim():!roles.value.includes('super_admin')||!original.can_review||!rosterReviewBasisValid(reviewBasis.value)))return;const t=ticket(),n=detailSeq,body=action==='revoke'?{expected_revision:original.revision,reason:reason.value}:{expected_revision:original.revision,expected_content_hash:original.content_hash,decision:action,review_basis_note:reviewBasis.value};acting.value=true;try{const response=await(action==='revoke'?revokeRosterPlan:reviewRosterPlan)(original.plan_id,body),row=response.data;if(!current(t)||n!==detailSeq)return;if(!await verifyRosterPlan(row,original.department_id,{audit:props.governance})||row.audit_only!==roles.value.includes('super_admin')||!await verifyRosterPlanTransition(row,original,action,body))throw new Error('排班计划治理回执与原件或本次CAS依据不一致');if(!current(t)||n!==detailSeq)return;detail.value=row;reviewBasis.value=reason.value='';invalidate();await load();}catch(failure){if(current(t)&&n===detailSeq)detailError.value=failure?.message||'排班计划治理失败';}finally{if(current(t)&&n===detailSeq)acting.value=false;}}
function openCreator(){formKey.value++;formValid.value=false;createError.value='';invalidate();creatorOpen.value=true;}
async function sourceChanged(){invalidate();notice.value='原来源已变化，旧计划与集合预览已清除；须重新捕获审核。';await refresh();}
watch(()=>props.departmentId,value=>{department.value=value;},{flush:'sync'});watch(department,value=>emit('department-change',value),{flush:'sync'});watch(identity,()=>{reset();refresh();},{immediate:true,flush:'sync'});onDeactivated(()=>{paused=true;reset();});onActivated(()=>{if(paused){paused=false;reset();refresh();}});onBeforeUnmount(()=>{alive=false;reset();});
</script>
<style scoped>p{line-height:1.7}.hash,pre{overflow-wrap:anywhere;white-space:pre-wrap}pre{max-height:550px;overflow:auto}.el-button{margin:8px 8px 8px 0}.el-select{min-width:230px}</style>
